import numpy as np
from scipy import stats
from sklearn.metrics import roc_auc_score
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'copy_number':
            if feats.n > 2:  # Avoid division by zero
                t_stat = feats.x[:, i].std() * (feats.x[feats.y==1, i].mean() - feats.x[feats.y==0, i].mean())
                p_val = 2 * (1 - stats.t.cdf(abs(t_stat), feats.n - 2))
                if p_val < 0.05:
                    sig_features.append((fid, t_stat, p_val))

    # Sort by effect size (absolute t-statistic)
    sig_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Get top features
    top_features = [f[0] for f in sig_features[:MAX_DRIVERS]]

    # Check for correlations and remove near-duplicates
    corr_pairs = []
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if i < feats.x.shape[1] and j < feats.x.shape[1]:  # Ensure indices valid
                try:
                    r = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
                    if abs(r) >= 0.6:
                        corr_pairs.append((feats.ids[i], feats.ids[j]))
                except:
                    continue

    # Build set of correlated features
    correlated_groups = []
    used = set()

    for a, b in corr_pairs:
        if a in used or b in used:
            continue
        group = {a, b}
        used.add(a)
        used.add(b)
        # Add transitive correlations
        for c, d in corr_pairs:
            if (c in group or d in group) and (c not in used and d not in used):
                group.add(c)
                group.add(d)
                used.add(c)
                used.add(d)
        correlated_groups.append(list(group))

    # Select representative from each group (prefer clinical/copy_number)
    selected_features = []
    for group in correlated_groups:
        # Prefer clinical or copy_number over expression
        group_types = []
        for fid in group:
            if fid in feats.ids:
                idx = feats.column(fid)
                if idx < len(feats.types):
                    group_types.append(feats.types[idx])
                else:
                    group_types.append('expression')
            else:
                group_types.append('expression')

        if group_types:  # Make sure we have types
            best_idx = min(range(len(group)), key=lambda i: (group_types[i] != 'clinical' and group_types[i] != 'copy_number', 
                                                            -abs(sig_features[feats.column(group[i])][1]) if i < len(sig_features) else 0))
            selected_features.append(group[best_idx])

    # Combine with top features
    all_selected = list(set(top_features + selected_features))

    # If we have more than MAX_DRIVERS, keep only top ones by effect size
    if len(all_selected) > MAX_DRIVERS:
        effect_sizes = []
        for fid in all_selected:
            if fid in feats.ids:
                idx = feats.column(fid)
                if idx < len(sig_features):
                    effect_sizes.append(abs(sig_features[idx][1]))
                else:
                    effect_sizes.append(0)
            else:
                effect_sizes.append(0)
        sorted_indices = np.argsort(effect_sizes)[::-1][:MAX_DRIVERS]
        all_selected = [all_selected[i] for i in sorted_indices]

    # For products, look for strong interactions between top features
    products = []
    for i, fid1 in enumerate(all_selected):
        for j, fid2 in enumerate(all_selected[i+1:], i+1):
            # Check if interaction term would be significant
            if fid1 in feats.ids and fid2 in feats.ids:
                idx1 = feats.column(fid1)
                idx2 = feats.column(fid2)
                if idx1 < feats.x.shape[1] and idx2 < feats.x.shape[1]:
                    prod = feats.x[:, idx1] * feats.x[:, idx2]
                    if len(prod) > 2:  # Avoid division by zero
                        t_stat = prod.std() * (prod[feats.y==1].mean() - prod[feats.y==0].mean())
                        p_val = 2 * (1 - stats.t.cdf(abs(t_stat), len(prod) - 2))
                        if p_val < 0.05:
                            products.append((fid1, fid2))

    # Drivers: use top features by effect size
    drivers = tuple([fid for fid in all_selected if fid in top_features])

    # Loadings: weight by effect size
    loadings = {}
    for fid in all_selected:
        if fid in feats.ids:
            idx = feats.column(fid)
            if idx < len(sig_features):
                t_stat = sig_features[idx][1]
                loadings[fid] = t_stat

    return Design(
        drivers=drivers,
        columns=tuple(all_selected),
        products=tuple(products),
        loadings=loadings
    )

